        triton.Config({'XBLOCK': 32, 'YBLOCK': 1},  num_warps=1),
        triton.Config({'XBLOCK': 32, 'YBLOCK': 2},  num_warps=1),
        # ... more configs ...
        triton.Config({'XBLOCK': 64, 'YBLOCK': 8},  num_warps=4),
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    ...

